<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Plus — CreativeHub Membership</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    :root {
      --primary: #F02D00;
      --primary-hover: #D12700;
      --foreground: #171717;
      --background: #FFFFFF;
      --surface: #FAFAFA;
      --surface-raised: #FFFFFF;
      --muted: #F5F5F5;
      --muted-foreground: #737373;
      --border: #E5E5E5;
      --border-strong: #D4D4D4;
      --accent-teal: #0D9488;
      --accent-teal-light: #CCFBF1;
      --success: #16A34A;
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
      --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
      --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
      --transition-fast: 150ms ease;
      --transition-base: 200ms ease;
      --transition-slow: 300ms ease;
      --font-heading: 'Inter', system-ui, sans-serif;
      --font-body: 'DM Sans', system-ui, sans-serif;
    }
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    html { scroll-behavior: smooth; }
    body {
      font-family: var(--font-body);
      color: var(--foreground);
      background: var(--background);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }
    img { max-width: 100%; display: block; }
    a { text-decoration: none; color: inherit; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    ul, ol { list-style: none; }

    .skip-link {
      position: absolute; top: -40px; left: 0;
      background: var(--primary); color: #fff;
      padding: 8px 16px; z-index: 10000;
      transition: top var(--transition-fast);
    }
    .skip-link:focus { top: 0; }

    .header {
      position: sticky; top: 0; z-index: 1000;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--border);
    }
    .header-inner {
      max-width: 1280px; margin: 0 auto;
      padding: 0 24px;
      display: flex; align-items: center; justify-content: space-between;
      height: 64px;
    }
    .logo {
      font-family: var(--font-heading);
      font-weight: 800; font-size: 22px;
      color: var(--foreground); letter-spacing: -0.5px;
      display: flex; align-items: center; gap: 8px;
    }
    .logo-mark {
      width: 32px; height: 32px; border-radius: var(--radius-sm);
      background: var(--primary);
      display: flex; align-items: center; justify-content: center;
    }
    .logo-mark svg { width: 18px; height: 18px; }
    .nav-desktop { display: none; }
    .nav-desktop a {
      font-size: 14px; font-weight: 500; color: var(--foreground);
      padding: 8px 12px; border-radius: var(--radius-sm);
      transition: background var(--transition-fast);
    }
    .nav-desktop a:hover { background: var(--muted); }
    .header-actions { display: flex; align-items: center; gap: 12px; }
    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      gap: 6px; padding: 10px 20px;
      font-size: 14px; font-weight: 600; border-radius: var(--radius-md);
      transition: all var(--transition-fast);
      white-space: nowrap;
    }
    .btn-primary { background: var(--primary); color: #fff; }
    .btn-primary:hover { background: var(--primary-hover); transform: translateY(-1px); }
    .btn-ghost { background: transparent; color: var(--foreground); border: 1px solid var(--border); }
    .btn-ghost:hover { background: var(--muted); border-color: var(--border-strong); }
    .btn-sm { padding: 8px 16px; font-size: 13px; }
    .btn-lg { padding: 14px 28px; font-size: 16px; border-radius: var(--radius-lg); }
    .mobile-menu-btn { display: flex; padding: 8px; }

    .mobile-menu {
      position: fixed; inset: 0; z-index: 2000;
      background: rgba(0,0,0,0.4);
      opacity: 0; pointer-events: none;
      transition: opacity var(--transition-base);
    }
    .mobile-menu.open { opacity: 1; pointer-events: auto; }
    .mobile-menu-panel {
      position: absolute; right: 0; top: 0; bottom: 0;
      width: 280px; background: #fff;
      transform: translateX(100%);
      transition: transform var(--transition-slow);
      padding: 24px; display: flex; flex-direction: column; gap: 8px;
    }
    .mobile-menu.open .mobile-menu-panel { transform: translateX(0); }
    .mobile-menu-panel a {
      padding: 12px; border-radius: var(--radius-sm);
      font-size: 15px; font-weight: 500;
      transition: background var(--transition-fast);
    }
    .mobile-menu-panel a:hover { background: var(--muted); }
    .mobile-menu-close { align-self: flex-end; padding: 8px; margin-bottom: 8px; }

    /* Hero */
    .hero {
      background: var(--foreground); color: #fff;
      padding: 64px 0 80px; text-align: center;
    }
    .hero-inner { max-width: 720px; margin: 0 auto; padding: 0 24px; }
    .hero h1 {
      font-family: var(--font-heading);
      font-size: clamp(32px, 5vw, 48px);
      font-weight: 800; line-height: 1.1;
      letter-spacing: -1.5px; margin-bottom: 16px;
    }
    .hero p {
      font-size: 18px; color: rgba(255,255,255,0.7);
      margin-bottom: 32px; max-width: 520px; margin-left: auto; margin-right: auto;
    }
    .hero .btn-primary {
      background: var(--primary); font-size: 16px; padding: 14px 32px;
    }
    .hero .btn-primary:hover { background: var(--primary-hover); }

    /* Pricing */
    .pricing-section { padding: 64px 0; background: var(--surface); }
    .pricing-inner { max-width: 720px; margin: 0 auto; padding: 0 24px; text-align: center; }
    .pricing-tabs {
      display: inline-flex; background: var(--muted);
      border-radius: var(--radius-lg); padding: 4px;
      margin-bottom: 32px;
    }
    .pricing-tab {
      padding: 10px 24px; font-size: 14px; font-weight: 600;
      border-radius: var(--radius-md); color: var(--muted-foreground);
      transition: all var(--transition-fast);
    }
    .pricing-tab.active { background: var(--surface-raised); color: var(--foreground); box-shadow: var(--shadow-sm); }
    .pricing-tab:hover:not(.active) { color: var(--foreground); }

    .pricing-card {
      background: var(--surface-raised);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      padding: 40px 32px;
      max-width: 420px; margin: 0 auto;
      text-align: left;
      position: relative;
    }
    .pricing-card .badge-save {
      position: absolute; top: -12px; right: 24px;
      background: var(--success); color: #fff;
      font-size: 11px; font-weight: 700;
      padding: 5px 12px; border-radius: var(--radius-sm);
      text-transform: uppercase; letter-spacing: 0.5px;
    }
    .pricing-card .price {
      font-family: var(--font-heading);
      font-size: 42px; font-weight: 800; letter-spacing: -1px;
      margin-bottom: 4px;
    }
    .pricing-card .price-period { font-size: 16px; color: var(--muted-foreground); font-weight: 400; }
    .pricing-card .billed { font-size: 14px; color: var(--muted-foreground); margin-bottom: 24px; }
    .pricing-card .credit-note {
      display: flex; align-items: center; gap: 8px;
      font-size: 14px; color: var(--foreground);
      background: var(--accent-teal-light);
      padding: 10px 14px; border-radius: var(--radius-sm);
      margin-bottom: 24px;
    }
    .pricing-card .credit-note svg { color: var(--accent-teal); flex-shrink: 0; }
    .pricing-card .btn-primary { width: 100%; justify-content: center; font-size: 16px; padding: 14px; }
    .pricing-card .terms {
      font-size: 12px; color: var(--muted-foreground);
      margin-top: 16px; text-align: center;
    }

    /* Sections */
    .section { padding: 64px 0; }
    .section-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
    .section-header {
      display: flex; align-items: flex-end; justify-content: space-between;
      margin-bottom: 32px; flex-wrap: wrap; gap: 16px;
    }
    .section-header h2 {
      font-family: var(--font-heading);
      font-size: clamp(24px, 3vw, 32px);
      font-weight: 700; letter-spacing: -0.5px;
    }
    .section-header a {
      font-size: 14px; font-weight: 600; color: var(--primary);
      display: flex; align-items: center; gap: 4px;
    }
    .section-header a:hover { text-decoration: underline; }

    /* Carousel */
    .carousel-wrap { position: relative; }
    .carousel {
      display: flex; gap: 16px;
      overflow-x: auto; scroll-snap-type: x mandatory;
      scroll-behavior: smooth;
      padding: 4px 4px 16px; margin: 0 -4px;
      -ms-overflow-style: none; scrollbar-width: none;
    }
    .carousel::-webkit-scrollbar { display: none; }
    .carousel-card {
      flex: 0 0 260px; max-width: 260px;
      scroll-snap-align: start;
      background: var(--surface-raised);
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      overflow: hidden;
      transition: transform var(--transition-base), box-shadow var(--transition-base);
    }
    .carousel-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
    .carousel-card-image {
      height: 150px; background: linear-gradient(135deg, #1a1a1a 0%, #333 100%);
      position: relative;
    }
    .carousel-card-image .badge-plus {
      position: absolute; top: 10px; left: 10px;
      background: var(--accent-teal); color: #fff;
      font-size: 10px; font-weight: 700;
      padding: 3px 8px; border-radius: var(--radius-sm);
      text-transform: uppercase; letter-spacing: 0.5px;
    }
    .carousel-card-body { padding: 16px; }
    .carousel-card-body h3 { font-family: var(--font-heading); font-size: 15px; font-weight: 600; margin-bottom: 6px; }
    .carousel-card-body p { font-size: 13px; color: var(--muted-foreground); margin-bottom: 10px; }
    .carousel-price { font-size: 16px; font-weight: 700; color: var(--primary); }
    .carousel-nav {
      display: flex; justify-content: center; gap: 12px; margin-top: 8px;
    }
    .carousel-nav button {
      width: 36px; height: 36px; border-radius: 50%;
      border: 1px solid var(--border); background: var(--surface-raised);
      display: flex; align-items: center; justify-content: center;
      transition: all var(--transition-fast);
    }
    .carousel-nav button:hover { background: var(--muted); }

    /* Features grid */
    .features-grid {
      display: grid;
      grid-template-columns: 1fr;
      gap: 24px;
    }
    .feature-card {
      background: var(--surface-raised);
      border-radius: var(--radius-md);
      border: 1px solid var(--border);
      padding: 28px;
      transition: transform var(--transition-base), box-shadow var(--transition-base);
    }
    .feature-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
    .feature-icon {
      width: 48px; height: 48px; border-radius: var(--radius-md);
      background: var(--accent-teal-light);
      display: flex; align-items: center; justify-content: center;
      margin-bottom: 16px;
    }
    .feature-icon svg { width: 24px; height: 24px; color: var(--accent-teal); }
    .feature-card h4 {
      font-family: var(--font-heading);
      font-size: 17px; font-weight: 600; margin-bottom: 8px;
    }
    .feature-card p {
      font-size: 14px; color: var(--muted-foreground); line-height: 1.55;
    }

    /* Certificates */
    .cert-section { background: var(--surface); }
    .cert-content {
      display: flex; flex-direction: column; gap: 40px; align-items: center;
    }
    .cert-text { max-width: 520px; }
    .cert-text h2 {
      font-family: var(--font-heading);
      font-size: clamp(24px, 3vw, 32px);
      font-weight: 700; letter-spacing: -0.5px; margin-bottom: 16px;
    }
    .cert-text p {
      font-size: 16px; color: var(--muted-foreground); line-height: 1.6; margin-bottom: 24px;
    }
    .cert-preview {
      width: 100%; max-width: 400px; aspect-ratio: 4/3;
      background: linear-gradient(135deg, #1a1a2d 0%, #2d2d4a 100%);
      border-radius: var(--radius-lg);
      border: 1px solid var(--border);
      display: flex; align-items: center; justify-content: center;
    }
    .cert-preview-inner {
      width: 80%; height: 70%;
      background: var(--surface-raised);
      border-radius: var(--radius-md);
      border: 2px solid var(--border);
      display: flex; flex-direction: column; align-items: center; justify-content: center;
      gap: 12px;
    }
    .cert-preview-inner svg { color: var(--accent-teal); }
    .cert-preview-inner span { font-size: 13px; font-weight: 600; color: var(--muted-foreground); }

    /* FAQ */
    .faq-list { max-width: 720px; margin: 0 auto; }
    .faq-item {
      border-bottom: 1px solid var(--border);
    }
    .faq-question {
      display: flex; align-items: center; justify-content: space-between;
      width: 100%; padding: 20px 0;
      font-family: var(--font-heading);
      font-size: 16px; font-weight: 600; text-align: left;
      color: var(--foreground);
      transition: color var(--transition-fast);
    }
    .faq-question:hover { color: var(--primary); }
    .faq-question svg {
      flex-shrink: 0; margin-left: 16px;
      transition: transform var(--transition-fast);
      color: var(--muted-foreground);
    }
    .faq-item.open .faq-question svg { transform: rotate(180deg); }
    .faq-answer {
      max-height: 0; overflow: hidden;
      transition: max-height var(--transition-slow), padding var(--transition-slow);
    }
    .faq-item.open .faq-answer {
      max-height: 300px;
      padding-bottom: 20px;
    }
    .faq-answer p {
      font-size: 15px; color: var(--muted-foreground); line-height: 1.6;
    }

    /* Footer */
    .footer {
      background: var(--foreground); color: #fff;
      padding: 56px 0 32px;
    }
    .footer-inner { max-width: 1280px; margin: 0 auto; padding: 0 24px; }
    .footer-grid { display: grid; grid-template-columns: 1fr; gap: 8px; }
    .footer-section { border-bottom: 1px solid rgba(255,255,255,0.08); }
    .footer-section:last-child { border-bottom: none; }
    .footer-section-header {
      display: flex; align-items: center; justify-content: space-between;
      padding: 16px 0;
      font-family: var(--font-heading);
      font-size: 14px; font-weight: 600;
      cursor: pointer; user-select: none;
    }
    .footer-section-header svg { transition: transform var(--transition-fast); opacity: 0.6; }
    .footer-section.open .footer-section-header svg { transform: rotate(180deg); }
    .footer-links { max-height: 0; overflow: hidden; transition: max-height var(--transition-slow); }
    .footer-section.open .footer-links { max-height: 600px; }
    .footer-links a { display: block; padding: 6px 0; font-size: 13px; color: rgba(255,255,255,0.6); transition: color var(--transition-fast); }
    .footer-links a:hover { color: #fff; }
    .footer-bottom {
      margin-top: 40px; padding-top: 24px;
      border-top: 1px solid rgba(255,255,255,0.08);
      display: flex; flex-direction: column; gap: 16px;
    }
    .footer-bottom p { font-size: 13px; color: rgba(255,255,255,0.5); }
    .footer-apps { display: flex; gap: 12px; }
    .footer-apps a {
      display: inline-flex; align-items: center; gap: 6px;
      padding: 8px 14px; border-radius: var(--radius-sm);
      border: 1px solid rgba(255,255,255,0.15);
      font-size: 12px; font-weight: 500; color: #fff;
      transition: background var(--transition-fast);
    }
    .footer-apps a:hover { background: rgba(255,255,255,0.08); }
    .footer-lang { display: flex; flex-wrap: wrap; gap: 8px 16px; }
    .footer-lang a { font-size: 13px; color: rgba(255,255,255,0.5); transition: color var(--transition-fast); }
    .footer-lang a:hover { color: #fff; }

    @media (min-width: 640px) {
      .features-grid { grid-template-columns: repeat(2, 1fr); }
    }
    @media (min-width: 768px) {
      .nav-desktop { display: flex; align-items: center; gap: 4px; }
      .mobile-menu-btn { display: none; }
      .cert-content { flex-direction: row; }
      .footer-grid { grid-template-columns: repeat(3, 1fr); gap: 32px; }
      .footer-section { border-bottom: none !important; }
      .footer-section-header { cursor: default; padding: 0 0 12px; }
      .footer-section-header svg { display: none; }
      .footer-links { max-height: none !important; }
      .footer-bottom { flex-direction: row; justify-content: space-between; align-items: center; }
    }
    @media (min-width: 1024px) {
      .features-grid { grid-template-columns: repeat(3, 1fr); }
      .footer-grid { grid-template-columns: repeat(5, 1fr); }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation-duration: 0.01ms !important; animation-iteration-count: 1 !important; transition-duration: 0.01ms !important; }
      html { scroll-behavior: auto; }
    }
    :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; }
  </style>
</head>
<body>
  <a href="#main" class="skip-link">Skip to main content</a>

  <header class="header">
    <div class="header-inner">
      <a href="index.html" class="logo">
        <span class="logo-mark">
          <svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2L2 7l10 5 10-5-10-5z"/><path d="M2 17l10 5 10-5"/><path d="M2 12l10 5 10-5"/></svg>
        </span>
        CreativeHub
      </a>
      <nav class="nav-desktop" aria-label="Main navigation">
        <a href="courses.html">Courses</a>
        <a href="projects.html">Projects</a>
        <a href="plus.html">Plus</a>
      </nav>
      <div class="header-actions">
        <a href="login.html" class="btn btn-ghost btn-sm">Log in</a>
        <a href="plus.html" class="btn btn-primary btn-sm">Join for Free</a>
        <button class="mobile-menu-btn" id="mobileMenuBtn" aria-label="Open menu" aria-expanded="false">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 6h16M4 12h16M4 18h16"/></svg>
        </button>
      </div>
    </div>
  </header>

  <div class="mobile-menu" id="mobileMenu" aria-hidden="true">
    <div class="mobile-menu-panel">
      <button class="mobile-menu-close" id="mobileMenuClose" aria-label="Close menu">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 6 6 18M6 6l12 12"/></svg>
      </button>
      <a href="courses.html">Courses</a>
      <a href="projects.html">Projects</a>
      <a href="plus.html">Plus</a>
      <a href="login.html">Log in</a>
      <a href="plus.html" class="btn btn-primary" style="margin-top:8px;">Join for Free</a>
    </div>
  </div>

  <main id="main">
    <!-- Hero -->
    <section class="hero" aria-label="Plus membership hero">
      <div class="hero-inner">
        <h1>Unlock your creative potential with Plus</h1>
        <p>Watch thousands of courses for free, get certificates, and exchange credits for any course on the platform.</p>
        <a href="#pricing" class="btn btn-primary btn-lg">Start your free trial</a>
      </div>
    </section>

    <!-- Pricing -->
    <section class="pricing-section" id="pricing" aria-labelledby="pricing-heading">
      <div class="pricing-inner">
        <h2 id="pricing-heading" style="font-family:var(--font-heading); font-size:clamp(24px,3vw,32px); font-weight:700; letter-spacing:-0.5px; margin-bottom:8px;">Choose your plan</h2>
        <p style="font-size:16px; color:var(--muted-foreground); margin-bottom:32px;">Cancel subscription renewal whenever you want.</p>

        <div class="pricing-tabs" role="tablist" aria-label="Pricing plans">
          <button class="pricing-tab active" id="tabYearly" role="tab" aria-selected="true" aria-controls="yearlyPlan">Yearly</button>
          <button class="pricing-tab" id="tabMonthly" role="tab" aria-selected="false" aria-controls="monthlyPlan">Monthly</button>
        </div>

        <div id="yearlyPlan" role="tabpanel" aria-labelledby="tabYearly">
          <div class="pricing-card">
            <span class="badge-save">Save 57%</span>
            <div class="price">$14.59<span class="price-period">/month</span></div>
            <p class="billed">Billed as $174.50/year</p>
            <div class="credit-note">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
              12 Plus credits every year
            </div>
            <button class="btn btn-primary btn-lg">Subscribe Yearly</button>
            <p class="terms">After one year, renewal price will be the full amount of $349.</p>
          </div>
        </div>

        <div id="monthlyPlan" role="tabpanel" aria-labelledby="tabMonthly" style="display:none;">
          <div class="pricing-card">
            <div class="price">$33.90<span class="price-period">/month</span></div>
            <p class="billed">Billed monthly</p>
            <div class="credit-note">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg>
              1 Plus credit per month
            </div>
            <button class="btn btn-primary btn-lg">Subscribe Monthly</button>
            <p class="terms">Cancel subscription renewal whenever you want.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- Course Catalog Carousel -->
    <section class="section" aria-labelledby="catalog-heading">
      <div class="section-inner">
        <div class="section-header">
          <h2 id="catalog-heading">+1,000 courses FREE with Plus</h2>
          <a href="courses.html">Explore catalog <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="m9 18 6-6-6-6"/></svg></a>
        </div>
        <div class="carousel-wrap">
